// Universal WhatsApp Payload Parser (Meta Cloud API, Evolution API, and Local Simulator)
const body = $input.item.json.body || $input.item.json;
const query = $input.item.json.query || {};

// 1. Meta Webhook Verification Challenge (GET / POST)
if (query['hub.mode'] === 'subscribe' && query['hub.challenge']) {
  return [{
    json: {
      is_challenge: true,
      challenge_response: query['hub.challenge']
    }
  }];
}

let customerPhone = '';
let customerName = 'Guest Customer';
let messageText = '';
let messageId = '';
let provider = 'unknown';

// 2. Meta WhatsApp Cloud API Structure
if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value?.messages) {
  const value = body.entry[0].changes[0].value;
  const msg = value.messages[0];
  const contact = value.contacts ? value.contacts[0] : null;

  if (msg && msg.type === 'text') {
    customerPhone = msg.from;
    customerName = contact?.profile?.name || 'Customer';
    messageText = msg.text.body.trim();
    messageId = msg.id;
    provider = 'meta_cloud';
  }
}
// 3. Evolution API / Baileys Structure
else if (body.data && body.data.key) {
  customerPhone = (body.data.key.remoteJid || '').replace('@s.whatsapp.net', '');
  customerName = body.data.pushName || 'Customer';
  messageText = body.data.message?.conversation || body.data.message?.extendedTextMessage?.text || '';
  messageId = body.data.key.id;
  provider = 'evolution_api';
}
// 4. Generic / Direct Simulation Payload
else if (body.phone && (body.message || body.text)) {
  customerPhone = String(body.phone).replace(/[^0-9]/g, '');
  customerName = body.name || 'Brandon Clark';
  messageText = (body.message || body.text).trim();
  messageId = 'sim-' + Date.now();
  provider = 'simulator';
}

// Skip empty or delivery receipts
if (!messageText || !customerPhone) {
  return [{
    json: {
      is_valid_message: false,
      reason: 'Empty text or delivery receipt event'
    }
  }];
}

return [{
  json: {
    is_valid_message: true,
    customer_phone: customerPhone,
    customer_name: customerName,
    message_text: messageText,
    message_id: messageId,
    provider: provider,
    timestamp: new Date().toISOString()
  }
}];

// American Restaurant Menu Provider Tool (USD Pricing)
const menu = {
  "Artisan Burgers": [
    { name: "The Classic Bacon Cheeseburger", price: "$13.99", desc: "Angus beef, applewood bacon, aged cheddar, house relish on brioche" },
    { name: "Smoky Texas BBQ Brisket Burger", price: "$16.50", desc: "Double smash patties, smoked brisket, crispy onion rings, BBQ sauce" },
    { name: "Crispy Nashville Hot Chicken", price: "$14.25", desc: "Buttermilk fried chicken, hot honey glaze, dill pickles, coleslaw" },
    { name: "Truffle Mushroom Swiss", price: "$15.75", desc: "Prime beef, sautéed cremini mushrooms, Swiss, black truffle aioli" }
  ],
  "Woodfired Pizzas (14\" Large)": [
    { name: "Brooklyn Pepperoni Feast", price: "$21.99", desc: "Sourdough crust, San Marzano sauce, cupping pepperoni, hot honey drizzle" },
    { name: "Smoked BBQ Chicken Pizza", price: "$19.50", desc: "Grilled chicken, red onions, smoked gouda, cilantro, hickory BBQ base" },
    { name: "Four-Cheese Margherita", price: "$18.25", desc: "Fresh mozzarella, fontina, gorgonzola, parmesan, fresh basil" }
  ],
  "Appetizers & Sides": [
    { name: "Loaded Truffle Parmesan Fries", price: "$7.50", desc: "Hand-cut fries, white truffle oil, shaved parmesan, garlic aioli" },
    { name: "Buffalo Wings (8 Pcs)", price: "$11.99", desc: "Crispy jumbo wings, classic buffalo butter glaze, blue cheese dip" },
    { name: "Mozzarella Sticks (6 Pcs)", price: "$8.25", desc: "Beer-battered golden sticks with warm marinara dipping sauce" }
  ],
  "Beverages & Desserts": [
    { name: "Hand-Spun Salted Caramel Shake", price: "$6.50", desc: "Vanilla bean ice cream, caramel fudge, pretzel crumbles" },
    { name: "Fresh Strawberry Lemonade", price: "$4.75", desc: "Muddled strawberries, California lemons, cane sugar" },
    { name: "Iced Cold Brew Coffee", price: "$4.25", desc: "Slow-steeped organic cold brew over craft ice" },
    { name: "Classic Coca-Cola Can (12 oz)", price: "$2.50", desc: "Chilled can of soda" },
    { name: "Warm Cast-Iron Chocolate Chip Cookie", price: "$8.50", desc: "Skillet cookie with Madagascar vanilla gelato" }
  ]
};

let output = "📋 *BISTRO GOURMET OFFICIAL MENU (USD)*\n\n";
for (const [cat, items] of Object.entries(menu)) {
  output += `🍔 *${cat.toUpperCase()}*\n`;
  for (const item of items) {
    output += `• *${item.name}* - ${item.price}\n  _${item.desc}_\n`;
  }
  output += "\n";
}
output += "🛵 *Delivery Fee*: $3.99 flat\n⏱️ *Average Delivery Time*: 30-40 minutes";
return output;

// Create Restaurant Order & Dispatch Alert to Kitchen Number B (USD Edition)
let orderData = {};
try {
  orderData = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  orderData = { raw_query: String(query) };
}

const orderId = 'ORD-' + Math.floor(1000 + Math.random() * 9000);
const customerName = orderData.customer_name || 'Michael Johnson';
const customerPhone = orderData.customer_phone || '+1 (555) 234-5678';
const address = orderData.delivery_address || '742 Evergreen Terrace, Springfield, OR 97477';
const total = orderData.total_amount ? Number(orderData.total_amount).toFixed(2) : '35.48';
const notes = orderData.special_notes || 'None';

let itemsFormatted = '';
if (Array.isArray(orderData.items) && orderData.items.length > 0) {
  itemsFormatted = orderData.items.map(i => `• ${i.qty || 1}x ${i.item || i.name} ($${Number(i.total || (i.price * (i.qty || 1))).toFixed(2)})`).join('\n');
} else if (orderData.items) {
  itemsFormatted = String(orderData.items);
} else {
  itemsFormatted = 'Confirmed food items';
}

return JSON.stringify({
  success: true,
  order_number: orderId,
  customer_name: customerName,
  customer_phone: customerPhone,
  delivery_address: address,
  items_summary: itemsFormatted,
  total_amount_usd: '$' + total,
  status: 'received',
  estimated_time: '30-40 minutes',
  kitchen_dispatched: true,
  message: `Order ${orderId} successfully placed! It has been dispatched to Kitchen WhatsApp (Number B) & KDS Dashboard.`
});

// Live Order Status Tracker Tool (US Kitchen)
const input = String(query).trim().toUpperCase();
const match = input.match(/ORD-\d{4}/);
const orderId = match ? match[0] : (input.length > 0 ? input : 'ORD-2041');

return JSON.stringify({
  success: true,
  order_number: orderId,
  status: 'preparing',
  status_text: '👨‍🍳 Chef is currently preparing your fresh order in the kitchen.',
  estimated_remaining_mins: 15,
  delivery_status: 'Will dispatch with driver shortly',
  message: `Your order ${orderId} is being prepared in the kitchen. Estimated delivery in ~15-20 minutes!`
});

// Order Cancellation Tool
const input = String(query).trim();
const match = input.match(/ORD-\d{4}/i);
const orderId = match ? match[0].toUpperCase() : 'your order';

return JSON.stringify({
  success: true,
  order_number: orderId,
  status: 'cancelled',
  message: `Order ${orderId} has been successfully cancelled before kitchen prep started. No cancellation fees apply.`
});
